// PreToolUse hook: blocks Edit and Write on the file .env (exit code 2)
let d = "";
process.stdin.on("data", c => d += c).on("end", () => {
  const p = (JSON.parse(d).tool_input || {}).file_path || "";
  if (/(^|[\\/])\.env$/.test(p)) {
    console.error("Blocked by hook: .env is protected.");
    process.exit(2);
  }
  process.exit(0);
});
